update activities set
  goal_one_line_hi = 'लक्ष्य: बच्चे को बिना सहारे अपने आप बैठने में मदद करना।',
  measuring_now_hi = 'आप हर प्रयास दर्ज करते हैं · हम समय रिकॉर्ड करते हैं',
  what_this_is_hi = 'बच्चा बिना सहारे फर्श पर बैठता है और अपनी चाही हुई चीज़ की ओर हाथ बढ़ाता है, आप इतने पास कि ज़रूरत पड़ने पर संभाल सकें।',
  why_we_do_it_hi = 'स्थिर बैठना बाकी सब कुछ की नींव है — हाथों का उपयोग, खेलना, आगे चलकर खड़ा होना। जो बच्चा बैठ नहीं पाता, वह अपने हाथ खोजने के लिए मुक्त नहीं कर पाता।',
  why_this_works_hi = 'धड़ का नियंत्रण क्रमबद्ध अभ्यास से बनता है: पहले छोटी अवधि, फिर लंबी, और सहारा थोड़ा-थोड़ा हटाते हुए। चाही हुई चीज़ की ओर हाथ बढ़ाना उस स्थिति में बने रहने का कारण देता है।',
  what_good_looks_like_hi = 'शुरुआत में बच्चा एक-दो सेकंड में गिर सकता है, या पीठ पर हाथ चाहिए हो सकता है। यह अच्छा चल रहा है जब वे ज़्यादा देर बैठें, डगमगाने पर खुद को संभालें, और बिना गिरे हाथ बढ़ा सकें।',
  what_we_measure_how_hi = 'आप हर प्रयास टैप करके दर्ज करते हैं — कितनी देर बैठे और कितनी मदद चाहिए थी। प्लेटफ़ॉर्म आपके स्कोर और गतिविधि का समय रिकॉर्ड करता है।',
  how_this_helps_hi = 'आपके स्कोर से रिकॉर्ड बनता है कि बैठना कितनी देर टिकता है और सहारा कैसे कम हो रहा है, सत्र-दर-सत्र, बिना किसी कागज़ी काम के।',
  what_we_dont_measure_hi = 'कैमरा बच्चे का शरीर या मुद्रा नहीं देखता। स्थिर कैमरा बैठना नहीं माप सकता। आप इसे दर्ज करते हैं — प्लेटफ़ॉर्म वही रिकॉर्ड करता है जो आप टैप करते हैं और समय मापता है। सेंसर हार्डवेयर आने पर यह बदलेगा।',
  mastery_behaviour_hi = 'बच्चा बिना सहारे बैठता है और बिना संतुलन खोए खिलौने की ओर हाथ बढ़ाता है।',
  therapist_steps_hi = '["बच्चे को चटाई पर बिठाएँ, पैर आराम से फैले हुए।","पसंदीदा खिलौना ठीक सामने रखें, आसानी से पहुँच में।","पास रहें पर पकड़ें नहीं — हाथ तैयार रखें, थामे नहीं।","हर प्रयास के बाद दर्ज करें कि कितनी देर बैठे और कितनी मदद लगी।"]'::jsonb,
  materials_required_hi = '["फर्श की चटाई","एक पसंदीदा खिलौना"]'::jsonb,
  updated_at = now()
where id = 'PHY-01';

update activities set
  goal_one_line_hi = 'लक्ष्य: बच्चे को चाही हुई चीज़ की ओर घुटनों के बल चलने में मदद करना।',
  measuring_now_hi = 'आप हर प्रयास दर्ज करते हैं · हम समय रिकॉर्ड करते हैं',
  what_this_is_hi = 'बच्चा चाही हुई चीज़ तक पहुँचने के लिए थोड़ी दूर घुटनों के बल चलता है, और सफल होने पर दूरी बढ़ाई जाती है।',
  why_we_do_it_hi = 'घुटनों के बल चलना हाथ और पैर की ताकत बनाता है, और शरीर के दोनों हिस्सों को साथ काम करना सिखाता है। यह चलने से पहले आता है और उसमें मदद करता है।',
  why_this_works_hi = 'यहाँ निर्देश से ज़्यादा प्रेरणा मायने रखती है। बच्चा किसी अनुरोध की तुलना में अपनी चाही हुई चीज़ की ओर ज़्यादा दूर तक चलता है। ताकत बढ़ने के साथ दूरी धीरे-धीरे बढ़ाई जाती है।',
  what_good_looks_like_hi = 'शुरुआत में बच्चा कुछ इंच खिसक सकता है या घिसटकर चल सकता है। यह अच्छा चल रहा है जब वे ज़्यादा दूरी तय करें, हाथ-पैर बारी-बारी चलाएँ, और बिना ज़्यादा कहे जाएँ।',
  what_we_measure_how_hi = 'आप हर प्रयास टैप करके दर्ज करते हैं — लगभग कितनी दूर और कितनी मदद। प्लेटफ़ॉर्म आपके स्कोर और समय रिकॉर्ड करता है।',
  how_this_helps_hi = 'दूरी और मदद के स्तर का एक जैसा रिकॉर्ड, ताकि ताकत और समन्वय की प्रगति याद रखने की बजाय दिखाई दे।',
  what_we_dont_measure_hi = 'कैमरा घुटनों के बल चलना नहीं देखता — बच्चा फर्श पर है, लैपटॉप से दूर। आप दर्ज करते हैं; प्लेटफ़ॉर्म आपके टैप रिकॉर्ड करता है। सेंसर हार्डवेयर आने पर यह बदलेगा।',
  mastery_behaviour_hi = 'बच्चा खिलौने तक पूरी तय दूरी बिना मदद के घुटनों के बल चलकर पहुँचता है।',
  therapist_steps_hi = '["बच्चे को चटाई पर हाथों और घुटनों पर रखें।","पसंदीदा खिलौना थोड़ी दूर आगे रखें।","बिना उठाए उन्हें उसकी ओर बढ़ने के लिए प्रोत्साहित करें।","दर्ज करें कि कितनी दूर गए और कितनी मदद चाहिए थी।"]'::jsonb,
  materials_required_hi = '["फर्श की चटाई","एक पसंदीदा खिलौना"]'::jsonb,
  updated_at = now()
where id = 'PHY-02';

update activities set
  goal_one_line_hi = 'लक्ष्य: बच्चे को खुद को खींचकर खड़ा होने में मदद करना।',
  measuring_now_hi = 'आप हर प्रयास दर्ज करते हैं · हम समय रिकॉर्ड करते हैं',
  what_this_is_hi = 'बच्चा नीची मज़बूत सतह का सहारा लेकर बैठने से खड़े होने तक खुद को खींचता है, ऊपर रखी चीज़ की ओर हाथ बढ़ाते हुए।',
  why_we_do_it_hi = 'खींचकर खड़ा होना पैरों की ताकत बनाता है और बच्चे को सिखाता है कि खुद कैसे खड़ा हुआ जाए — पकड़कर चलने और फिर चलने से पहले का कदम।',
  why_this_works_hi = 'उठाने की बजाय बच्चे को खुद खींचने देना ही ताकत बनाता है। खिलौना कारण देता है; सतह सहारा देती है।',
  what_good_looks_like_hi = 'शुरुआत में बच्चे का ज़्यादातर वज़न आपको उठाना पड़ सकता है। यह अच्छा चल रहा है जब वे लगभग अपने आप खींचकर खड़े हों और बैठने से पहले ज़्यादा देर खड़े रहें।',
  what_we_measure_how_hi = 'आप हर प्रयास टैप करके दर्ज करते हैं — अपने आप खड़े हुए या मदद से, और लगभग कितनी देर खड़े रहे। प्लेटफ़ॉर्म आपके स्कोर और समय रिकॉर्ड करता है।',
  how_this_helps_hi = 'दिखाता है कि बच्चा समय के साथ कम मदद से खुद खड़ा हो रहा है या नहीं, सत्रों में एक जैसे दर्ज।',
  what_we_dont_measure_hi = 'कैमरा बच्चे का खड़ा होना या वे कैसे उठे यह नहीं देखता। आप दर्ज करते हैं; प्लेटफ़ॉर्म आपके टैप रिकॉर्ड करता है। सेंसर हार्डवेयर आने पर यह बदलेगा।',
  mastery_behaviour_hi = 'बच्चा अपने आप खींचकर खड़ा होता है और थोड़ी देर खड़ा रहता है।',
  therapist_steps_hi = '["बच्चे को नीची, मज़बूत सतह के पास बिठाएँ।","ऊपर एक खिलौना रखें, उनकी नज़र में।","उन्हें पकड़कर खींचने दें — संभालें, उठाएँ नहीं।","दर्ज करें कि अपने आप खड़े हुए या नहीं और कितनी देर खड़े रहे।"]'::jsonb,
  materials_required_hi = '["नीची मज़बूत मेज़ या बेंच","एक पसंदीदा खिलौना"]'::jsonb,
  updated_at = now()
where id = 'PHY-03';

update activities set
  goal_one_line_hi = 'लक्ष्य: बच्चे को पकड़कर बगल में कदम रखने में मदद करना।',
  measuring_now_hi = 'आप हर प्रयास दर्ज करते हैं · हम समय रिकॉर्ड करते हैं',
  what_this_is_hi = 'बच्चा पकड़े हुए नीची सतह के साथ बगल में चलता है, आगे रखे खिलौने तक पहुँचने के लिए।',
  why_we_do_it_hi = 'पकड़कर बगल में चलना खड़े होने और चलने के बीच का पुल है। यह एक पैर से दूसरे पर वज़न डालना सिखाता है जबकि हाथ अभी मदद करते हैं।',
  why_this_works_hi = 'वज़न बदलना ही असली कौशल है, और यह सहारे के साथ अभ्यास से विकसित होता है। खिलौना बस पहुँच से बाहर रखना कदम रखने की ज़रूरत बनाता है।',
  what_good_looks_like_hi = 'शुरुआत में बच्चा एक छोटा कदम रखे या नीचे बैठ जाए। यह अच्छा चल रहा है जब वे ज़्यादा कदम रखें, कम कसकर पकड़ें, और वज़न ज़्यादा सहजता से बदलें।',
  what_we_measure_how_hi = 'आप हर प्रयास टैप करके दर्ज करते हैं — लगभग कितने कदम और कितने स्थिर। प्लेटफ़ॉर्म आपके स्कोर और समय रिकॉर्ड करता है।',
  how_this_helps_hi = 'सत्रों में कदमों की गिनती और स्थिरता दिखाती है कि वज़न बदलना बेहतर हो रहा है या नहीं — चलना इसी पर निर्भर है।',
  what_we_dont_measure_hi = 'कैमरा बच्चे के कदम या संतुलन नहीं देखता — वे लैपटॉप से दूर, बगल में चल रहे हैं। आप दर्ज करते हैं; प्लेटफ़ॉर्म आपके टैप रिकॉर्ड करता है। सेंसर हार्डवेयर आने पर यह बदलेगा।',
  mastery_behaviour_hi = 'बच्चा नीचे बैठे बिना पूरी लंबाई तक पकड़कर चलकर खिलौने तक पहुँचता है।',
  therapist_steps_hi = '["बच्चे को नीची मज़बूत सतह पकड़कर खड़ा करें।","खिलौना उसी सतह पर थोड़ा आगे रखें, पहुँच से बाहर।","उन्हें बगल में कदम रखकर लेने दें।","दर्ज करें कि कितने कदम और कितने स्थिर थे।"]'::jsonb,
  materials_required_hi = '["नीची मज़बूत बेंच या सोफ़ा","साथ रखने के लिए खिलौने"]'::jsonb,
  updated_at = now()
where id = 'PHY-04';

update activities set
  goal_one_line_hi = 'लक्ष्य: बच्चे को सहारे के साथ चलने के कदम रखने में मदद करना।',
  measuring_now_hi = 'आप हर प्रयास दर्ज करते हैं · हम समय रिकॉर्ड करते हैं',
  what_this_is_hi = 'बच्चा आपके हाथ पकड़कर या स्थिर खिलौना धकेलते हुए आगे चलता है, और स्थिर होने पर सहारा कम किया जाता है।',
  why_we_do_it_hi = 'चलना वह लक्ष्य है जिसका ज़्यादातर परिवार इंतज़ार करते हैं। सहारे के साथ अभ्यास वह ताकत और संतुलन बनाता है जो अकेले चलने के लिए चाहिए।',
  why_this_works_hi = 'सहारा चरणों में कम किया जाता है — दो हाथ, एक हाथ, उँगलियाँ, फिर कुछ नहीं। हर चरण स्थिर होने तक अभ्यास किया जाता है।',
  what_good_looks_like_hi = 'शुरुआत में बच्चे को दोनों हाथ चाहिए हो सकते हैं और कदम छोटे और कड़े होंगे। यह अच्छा चल रहा है जब कदम लंबे और सहज हों, और एक हाथ काफ़ी हो।',
  what_we_measure_how_hi = 'आप हर प्रयास टैप करके दर्ज करते हैं — कदमों की गिनती और सहारे का स्तर। प्लेटफ़ॉर्म आपके स्कोर और समय रिकॉर्ड करता है।',
  how_this_helps_hi = 'सत्र-दर-सत्र सहारे के कम होने को दर्ज करता है, जो अकेले चलने की दिशा में असली प्रगति का माप है।',
  what_we_dont_measure_hi = 'कैमरा चलना, कदम या संतुलन नहीं देखता। स्थिर कैमरा यह नहीं माप सकता। आप दर्ज करते हैं; प्लेटफ़ॉर्म आपके टैप रिकॉर्ड करता है। सेंसर हार्डवेयर आने पर यह बदलेगा।',
  mastery_behaviour_hi = 'बच्चा एक हाथ पकड़कर तय दूरी तक चलता है।',
  therapist_steps_hi = '["बच्चे को अपने हाथ या धक्का देने वाला खिलौना पकड़ाकर खड़ा करें।","उनकी गति से धीरे-धीरे आगे चलें।","पकड़ धीरे-धीरे कम करें — पहले दो हाथ, फिर एक।","दर्ज करें कि कितने कदम और कितना सहारा चाहिए था।"]'::jsonb,
  materials_required_hi = '["धक्का देने वाला खिलौना या आपके हाथ"]'::jsonb,
  updated_at = now()
where id = 'PHY-05';

update activities set
  goal_one_line_hi = 'लक्ष्य: बच्चे को एक पैर पर संतुलन बनाने में मदद करना।',
  measuring_now_hi = 'आप हर प्रयास दर्ज करते हैं · हम समय रिकॉर्ड करते हैं',
  what_this_is_hi = 'बच्चा जितनी देर हो सके एक पैर पर खड़ा रहता है, आप पास में, दोनों तरफ़ अभ्यास करते हुए।',
  why_we_do_it_hi = 'एक पैर का संतुलन सीढ़ियों, गेंद मारने और स्थिर चलने के लिए चाहिए। यह यह भी दिखाता है कि बच्चा अपने शरीर को कितना नियंत्रित करता है।',
  why_this_works_hi = 'संतुलन लंबी की बजाय बार-बार छोटी अवधि से बेहतर होता है। साथ में गिनती बोलना इसे खेल बनाता है और बच्चे को हराने के लिए एक संख्या देता है।',
  what_good_looks_like_hi = 'शुरुआत में बच्चा एक सेकंड रुके या कुछ छूना पड़े। यह अच्छा चल रहा है जब वे ज़्यादा देर रुकें, दोनों पैरों पर कर सकें, और पास हाथ की ज़रूरत न हो।',
  what_we_measure_how_hi = 'आप हर प्रयास टैप करके सेकंड दर्ज करते हैं, हर तरफ़ के लिए। प्लेटफ़ॉर्म आपके स्कोर और गतिविधि का समय रिकॉर्ड करता है।',
  how_this_helps_hi = 'हर पैर के सेकंड-दर-सेकंड रिकॉर्ड सुधार दिखाते हैं और यह भी बताते हैं कि कोई एक तरफ़ कमज़ोर है या नहीं।',
  what_we_dont_measure_hi = 'कैमरा बच्चे का खड़ा होना या संतुलन नहीं देखता। आप दर्ज करते हैं; प्लेटफ़ॉर्म आपके टैप रिकॉर्ड करता है। सेंसर हार्डवेयर आने पर यह बदलेगा।',
  mastery_behaviour_hi = 'बच्चा दोनों पैरों पर तय समय तक एक पैर का संतुलन बनाए रखता है।',
  therapist_steps_hi = '["बच्चे के सामने इतने पास खड़े हों कि संभाल सकें।","एक पैर उठाकर रुकने को कहें।","साथ में गिनती बोलें — इसे खेल बनाएँ।","हर तरफ़ कितने सेकंड रुके, दर्ज करें।"]'::jsonb,
  materials_required_hi = '[]'::jsonb,
  updated_at = now()
where id = 'PHY-06';

update activities set
  goal_one_line_hi = 'लक्ष्य: बच्चे को सीधी रेखा पर एड़ी-से-पंजा चलने में मदद करना।',
  measuring_now_hi = 'आप हर प्रयास दर्ज करते हैं · हम समय रिकॉर्ड करते हैं',
  what_this_is_hi = 'बच्चा फर्श पर बनी रेखा पर एड़ी-से-पंजा चलता है, आप साथ चलते हुए।',
  why_we_do_it_hi = 'संकरी रेखा पर चलना चलते हुए नियंत्रित संतुलन माँगता है, जो स्थिर खड़े रहने से कठिन है। यह भीड़ वाली जगहों में सुरक्षित चलने में काम आता है।',
  why_this_works_hi = 'पैरों का आधार संकरा करने से संतुलन को ज़्यादा मेहनत करनी पड़ती है। दिखाई देने वाली रेखा बच्चे को खुद देखने लायक फ़ीडबैक देती है।',
  what_good_looks_like_hi = 'शुरुआत में बच्चा बार-बार बाहर निकले या पैर चौड़े करके चले। यह अच्छा चल रहा है जब वे रेखा पर ज़्यादा दूर रहें, एड़ी-से-पंजा रखें, और कम बार बाहर निकलें।',
  what_we_measure_how_hi = 'आप हर प्रयास टैप करके दर्ज करते हैं — तय की गई दूरी और रेखा से बाहर निकलने की गिनती। प्लेटफ़ॉर्म आपके स्कोर और समय रिकॉर्ड करता है।',
  how_this_helps_hi = 'सत्रों में बाहर निकलने की गिनती घटना गतिशील संतुलन के सुधार का साफ़, ईमानदार माप है।',
  what_we_dont_measure_hi = 'कैमरा बच्चे का चलना या रेखा पर रहना नहीं देखता। आप दर्ज करते हैं; प्लेटफ़ॉर्म आपके टैप रिकॉर्ड करता है। सेंसर हार्डवेयर आने पर यह बदलेगा।',
  mastery_behaviour_hi = 'बच्चा पूरी रेखा एड़ी-से-पंजा चलता है, एक से ज़्यादा बार बाहर निकले बिना।',
  therapist_steps_hi = '["फर्श पर टेप की सीधी रेखा बनाएँ।","बच्चे से उस पर एड़ी-से-पंजा चलने को कहें।","साथ चलें, संभालने के लिए तैयार पर पकड़े बिना।","दर्ज करें कि कितनी दूर गए और कितनी बार रेखा से बाहर हुए।"]'::jsonb,
  materials_required_hi = '["फर्श पर टेप या रस्सी"]'::jsonb,
  updated_at = now()
where id = 'PHY-07';

update activities set
  goal_one_line_hi = 'लक्ष्य: बच्चे को दोनों पैरों से एक साथ कूदने में मदद करना।',
  measuring_now_hi = 'आप हर प्रयास दर्ज करते हैं · हम समय रिकॉर्ड करते हैं',
  what_this_is_hi = 'बच्चा किसी निशान पर या उसके ऊपर से दोनों पैर एक साथ उठाकर और एक साथ उतारकर कूदता है।',
  why_we_do_it_hi = 'कूदने के लिए पैरों की ताकत और दोनों तरफ़ का एक साथ काम करना चाहिए। यह एक मील का पत्थर है जो दूसरे बच्चों के साथ मैदान में खेलने का रास्ता खोलता है।',
  why_this_works_hi = 'दो पैरों से कूदना एक पैर से कूदने से पहले विकसित होता है। दिखाई देने वाला निशान बच्चे को लक्ष्य देता है और सफलता स्पष्ट बनाता है।',
  what_good_looks_like_hi = 'शुरुआत में एक पैर पहले उठ सकता है, या बच्चा कूदने की बजाय कदम रखे। यह अच्छा चल रहा है जब दोनों पैर साथ उठें और साथ उतरें, और छलांग लंबी हो।',
  what_we_measure_how_hi = 'आप हर प्रयास टैप करके दर्ज करते हैं — दोनों पैर साथ थे या नहीं, और लगभग कितनी दूर। प्लेटफ़ॉर्म आपके स्कोर और समय रिकॉर्ड करता है।',
  how_this_helps_hi = 'सत्रों में सफल दो-पैर छलांगों की साफ़ गिनती, जो दिखाती है कि यह ढंग ठीक से बन गया है या नहीं।',
  what_we_dont_measure_hi = 'कैमरा छलांग, पैर या उतरना नहीं देखता। आप दर्ज करते हैं; प्लेटफ़ॉर्म आपके टैप रिकॉर्ड करता है। सेंसर हार्डवेयर आने पर यह बदलेगा।',
  mastery_behaviour_hi = 'बच्चा निशान के ऊपर से दोनों पैर साथ उठाकर और साथ उतारकर कूदता है।',
  therapist_steps_hi = '["फर्श पर कूदने के लिए एक निशान बनाएँ।","एक बार करके दिखाएँ — दोनों पैर साथ, साथ ही उतरना।","उन्हें कोशिश करने दें, पास रहते हुए।","दर्ज करें कि दोनों पैर साथ उठे और साथ उतरे या नहीं।"]'::jsonb,
  materials_required_hi = '["फर्श के निशान या एक नीची रेखा"]'::jsonb,
  updated_at = now()
where id = 'PHY-08';

update activities set
  goal_one_line_hi = 'लक्ष्य: बच्चे को हर सीढ़ी पर एक पैर रखकर चढ़ने में मदद करना।',
  measuring_now_hi = 'आप हर प्रयास दर्ज करते हैं · हम समय रिकॉर्ड करते हैं',
  what_this_is_hi = 'बच्चा छोटी सीढ़ियाँ चढ़ता है, हर सीढ़ी पर एक पैर रखकर, दोनों पैर एक ही सीढ़ी पर लाए बिना।',
  why_we_do_it_hi = 'सीढ़ियाँ हर जगह हैं — घर पर, स्कूल में, क्लिनिक में। उन्हें सुरक्षित और अपने आप चढ़ पाना असली रोज़मर्रा का कौशल है।',
  why_this_works_hi = 'बारी-बारी पैर रखने के लिए हर सीढ़ी पर एक पैर का सहारा चाहिए, इसलिए यह सीधे एक-पैर संतुलन पर बनता है। यह दोनों-पैर-साथ चढ़ने के बाद आता है।',
  what_good_looks_like_hi = 'शुरुआत में बच्चा हर सीढ़ी पर दोनों पैर लाए और रेलिंग कसकर पकड़े। यह अच्छा चल रहा है जब वे पैर बदलें, रेलिंग कम इस्तेमाल करें, और ज़्यादा सीढ़ियाँ चढ़ें।',
  what_we_measure_how_hi = 'आप हर प्रयास टैप करके दर्ज करते हैं — सीढ़ियों की गिनती, पैर बदले या नहीं, और रेलिंग का उपयोग। प्लेटफ़ॉर्म आपके स्कोर और समय रिकॉर्ड करता है।',
  how_this_helps_hi = 'दोनों-पैर-साथ से बारी-बारी पैर रखने तक के बदलाव को दर्ज करता है, जो यहाँ का नैदानिक मील का पत्थर है।',
  what_we_dont_measure_hi = 'कैमरा सीढ़ियाँ या बच्चे के पैर नहीं देखता। आप दर्ज करते हैं; प्लेटफ़ॉर्म आपके टैप रिकॉर्ड करता है। सेंसर हार्डवेयर आने पर यह बदलेगा।',
  mastery_behaviour_hi = 'बच्चा पूरी सीढ़ियाँ पैर बदल-बदलकर चढ़ता है, रेलिंग हल्के से या बिल्कुल इस्तेमाल किए बिना।',
  therapist_steps_hi = '["सीढ़ियों के नीचे बच्चे के बगल में खड़े हों।","हर सीढ़ी पर एक पैर रखकर चढ़ने को कहें।","उनके बराबर रहें, संभालने के लिए तैयार।","दर्ज करें कि कितनी सीढ़ियाँ और पैर बदल-बदलकर रखे या नहीं।"]'::jsonb,
  materials_required_hi = '["रेलिंग वाली छोटी सीढ़ियाँ"]'::jsonb,
  updated_at = now()
where id = 'PHY-09';

update activities set
  goal_one_line_hi = 'लक्ष्य: बच्चे को संतुलन बनाए रखते हुए गेंद मारने में मदद करना।',
  measuring_now_hi = 'आप हर प्रयास दर्ज करते हैं · हम समय रिकॉर्ड करते हैं',
  what_this_is_hi = 'बच्चा खड़े होकर स्थिर गेंद को आगे मारता है, बिना संतुलन खोए।',
  why_we_do_it_hi = 'गेंद मारने के लिए बच्चे को एक पैर पर संतुलन बनाना पड़ता है जबकि दूसरा घूमता है। यह संतुलन और समन्वय को उस चीज़ में जोड़ता है जो बच्चों को पसंद है।',
  why_this_works_hi = 'स्थिर गेंद का अभ्यास लुढ़कती गेंद से पहले किया जाता है। कौशल यह है कि दूसरे पैर के ज़ोर से घूमते समय एक पल के लिए एक पैर पर खड़ा रहना।',
  what_good_looks_like_hi = 'शुरुआत में बच्चा गेंद में चलकर टकरा सकता है या मारने के बाद गिर सकता है। यह अच्छा चल रहा है जब वे साफ़ झूले से मारें, खड़े रहें, और गेंद ज़्यादा दूर जाए।',
  what_we_measure_how_hi = 'आप हर प्रयास टैप करके दर्ज करते हैं — गेंद लगी, संतुलन बना रहा, और लगभग कितनी दूर गई। प्लेटफ़ॉर्म आपके स्कोर और समय रिकॉर्ड करता है।',
  how_this_helps_hi = 'गेंद लगने की सफलता को संतुलन बने रहने के साथ जोड़ता है, जिससे कौशल के दोनों हिस्से विकसित होते दिखते हैं।',
  what_we_dont_measure_hi = 'कैमरा गेंद मारना, गेंद, या बच्चे का संतुलन नहीं देखता। आप दर्ज करते हैं; प्लेटफ़ॉर्म आपके टैप रिकॉर्ड करता है। सेंसर हार्डवेयर आने पर यह बदलेगा।',
  mastery_behaviour_hi = 'बच्चा ज़्यादातर प्रयासों में गेंद आगे मारता है और खड़ा रहता है।',
  therapist_steps_hi = '["बच्चे के सामने नरम गेंद स्थिर रखें।","उसे आपकी ओर मारने को कहें।","उन्हें अपना संतुलन खुद ढूँढ़ने दें — पकड़ें नहीं।","दर्ज करें कि गेंद मारी और खड़े रहे या नहीं।"]'::jsonb,
  materials_required_hi = '["एक नरम गेंद"]'::jsonb,
  updated_at = now()
where id = 'PHY-10';

update activities set
  goal_one_line_hi = 'लक्ष्य: बच्चे को धीरे से फेंकी गेंद पकड़ने में मदद करना।',
  measuring_now_hi = 'आप हर प्रयास दर्ज करते हैं · हम समय रिकॉर्ड करते हैं',
  what_this_is_hi = 'बच्चा थोड़ी दूरी से छाती की ओर धीरे फेंकी गई बड़ी नरम गेंद पकड़ता है।',
  why_we_do_it_hi = 'पकड़ने के लिए बच्चे को चलती चीज़ देखनी पड़ती है और हाथ उससे मिलाने पड़ते हैं। यह हाथ-आँख का समन्वय और प्रतिक्रिया का समय बनाता है।',
  why_this_works_hi = 'बड़ी धीमी गेंदें छोटी तेज़ गेंदों से पहले पकड़ी जाती हैं, और छाती की ऊँचाई पहले। सफलता बढ़ने के साथ दूरी बढ़ाई जाती है।',
  what_good_looks_like_hi = 'शुरुआत में बच्चा देर से हाथ बंद करे या मुँह फेर ले। यह अच्छा चल रहा है जब वे समय पर हाथ तैयार करें और ज़्यादा बार रोकें या पकड़ें।',
  what_we_measure_how_hi = 'आप हर फेंक टैप करके दर्ज करते हैं — पकड़ी, शरीर से रोकी, या चूक गए। प्लेटफ़ॉर्म आपके स्कोर और समय रिकॉर्ड करता है।',
  how_this_helps_hi = 'हर फेंक का साफ़ रिकॉर्ड, जो सत्रों में रोकने से सच में पकड़ने की ओर बदलाव दिखाता है।',
  what_we_dont_measure_hi = 'कैमरा गेंद या पकड़ना नहीं देखता। आप दर्ज करते हैं; प्लेटफ़ॉर्म वही रिकॉर्ड करता है जो आप टैप करते हैं। सेंसर हार्डवेयर आने पर यह बदलेगा।',
  mastery_behaviour_hi = 'बच्चा ज़्यादातर फेंकों में गेंद शरीर से रोकने की बजाय हाथों से पकड़ता है।',
  therapist_steps_hi = '["बच्चे से थोड़ी दूर खड़े हों।","बड़ी नरम गेंद धीरे से उनकी छाती की ओर फेंकें।","हर बार फेंकने से पहले ''तैयार'' कहें।","दर्ज करें कि पकड़ी, शरीर से रोकी, या चूक गए।"]'::jsonb,
  materials_required_hi = '["एक बड़ी नरम गेंद"]'::jsonb,
  updated_at = now()
where id = 'PHY-11';

update activities set
  goal_one_line_hi = 'लक्ष्य: बच्चे को कई चुनौतियों से क्रम में गुज़रने में मदद करना।',
  measuring_now_hi = 'आप हर प्रयास दर्ज करते हैं · हम समय रिकॉर्ड करते हैं',
  what_this_is_hi = 'बच्चा एक छोटे कोर्स से गुज़रता है जिसमें कई हरकतें मिली हों — ऊपर से लाँघना, नीचे से जाना, साथ चलना, चारों ओर घूमना।',
  why_we_do_it_hi = 'असली गति कभी एक समय में एक कौशल नहीं होती। कोर्स बच्चे से हरकतें बदलने और क्रम याद रखने को कहता है, जो रोज़मर्रा की ज़िंदगी के ज़्यादा करीब है।',
  why_this_works_hi = 'कौशलों को क्रम में जोड़ना यह जाँचता है कि हर एक सचमुच स्थापित है या नहीं, और स्मृति की माँग जोड़ता है। हिस्से जोड़कर कठिनाई आसानी से बढ़ाई जा सकती है।',
  what_good_looks_like_hi = 'शुरुआत में बच्चे को हर बाधा पर याद दिलाना पड़ सकता है या वे हिस्से छोड़ें। यह अच्छा चल रहा है जब वे पूरा कोर्स क्रम में, कम याद दिलाने पर और ज़्यादा तेज़ी से पूरा करें।',
  what_we_measure_how_hi = 'आप हर दौर टैप करके दर्ज करते हैं — पूरे किए गए हिस्से और चाहिए मदद, और प्लेटफ़ॉर्म दौड़ का समय मापता है। आपके स्कोर और समय रिकॉर्ड होते हैं।',
  how_this_helps_hi = 'सत्रों में दौड़ का समय और पूरे हिस्से मिलकर गति-कौशल और क्रम की तस्वीर देते हैं, जो अकेले व्यायाम नहीं दिखाते।',
  what_we_dont_measure_hi = 'कैमरा कोर्स या बच्चे का उसमें से गुज़रना नहीं देखता। आप दर्ज करते हैं; प्लेटफ़ॉर्म आपके टैप और दौड़ का समय रिकॉर्ड करता है। सेंसर हार्डवेयर आने पर यह बदलेगा।',
  mastery_behaviour_hi = 'बच्चा बिना याद दिलाए पूरा कोर्स क्रम में पूरा करता है।',
  therapist_steps_hi = '["तीन-चार सरल बाधाएँ एक कतार में लगाएँ।","एक बार बच्चे को साथ ले जाकर हर हिस्सा दिखाएँ।","फिर उन्हें पूरा कोर्स खुद करने दें।","दर्ज करें कि कितने हिस्से पूरे किए और कितनी मदद चाहिए थी।"]'::jsonb,
  materials_required_hi = '["शंकु, तकिए, नीची बीम, सुरंग — जो उपलब्ध हो"]'::jsonb,
  updated_at = now()
where id = 'PHY-12';

update activities set
  goal_one_line_hi = 'लक्ष्य: बच्चे को एक पैर पर आगे उछलने में मदद करना।',
  measuring_now_hi = 'आप हर प्रयास दर्ज करते हैं · हम समय रिकॉर्ड करते हैं',
  what_this_is_hi = 'बच्चा छोटी चिह्नित दूरी पर एक पैर से आगे उछलता है, दोनों पैरों का अभ्यास करते हुए।',
  why_we_do_it_hi = 'उछलना कूदने से कठिन है — इसके लिए एक पैर पर ताकत और संतुलन चाहिए। यह मैदान के खेलों और स्कूल की PE में आता है।',
  why_this_works_hi = 'उछलना दो-पैर कूदने और एक-पैर खड़े होने के मज़बूत हो जाने के बाद विकसित होता है। दोनों तरफ़ अभ्यास दिखाता है कि कोई एक पैर पीछे है या नहीं।',
  what_good_looks_like_hi = 'शुरुआत में बच्चा एक उछाल कर पाए या दूसरा पैर नीचे रख दे। यह अच्छा चल रहा है जब वे लगातार कई उछाल लगाएँ, दोनों पैरों पर, और ज़्यादा दूरी तय करें।',
  what_we_measure_how_hi = 'आप हर प्रयास टैप करके हर पैर की लगातार उछालों की गिनती दर्ज करते हैं। प्लेटफ़ॉर्म आपके स्कोर और समय रिकॉर्ड करता है।',
  how_this_helps_hi = 'हर तरफ़ की उछाल गिनती प्रगति दिखाती है और पैरों के बीच का अंतर उजागर करती है, जो एक तरफ़ के अभ्यास से छिप जाता।',
  what_we_dont_measure_hi = 'कैमरा उछलना या कौन-सा पैर इस्तेमाल हुआ यह नहीं देखता। आप दर्ज करते हैं; प्लेटफ़ॉर्म आपके टैप रिकॉर्ड करता है। सेंसर हार्डवेयर आने पर यह बदलेगा।',
  mastery_behaviour_hi = 'बच्चा दूसरा पैर नीचे रखे बिना हर पैर पर तय संख्या में उछलता है।',
  therapist_steps_hi = '["फर्श पर एक छोटी दूरी चिह्नित करें।","बच्चे से उस पर एक पैर से उछलने को कहें।","पास रहें, संभालने के लिए तैयार।","हर पैर पर कितनी उछाल, दर्ज करें।"]'::jsonb,
  materials_required_hi = '["फर्श के निशान"]'::jsonb,
  updated_at = now()
where id = 'PHY-13';

update activities set
  goal_one_line_hi = 'लक्ष्य: बच्चे को निशाने पर सही फेंकने में मदद करना।',
