  why_this_works_hi = 'सटीकता तुरंत दिखाई देने वाले फ़ीडबैक से बेहतर होती है — बीनबैग अंदर गिरा या बाहर। दूरी तभी बढ़ाई जाती है जब सटीकता स्थिर हो।',
  what_good_looks_like_hi = 'शुरुआत में फेंक इधर-उधर जा सकती है या कम पड़ सकती है। यह अच्छा चल रहा है जब ज़्यादा निशाने पर लगें, फेंकने का ढंग सहज हो, और दूरी बढ़ाई जा सके।',
  what_we_measure_how_hi = 'आप हर फेंक टैप करके लगा या चूका दर्ज करते हैं। प्लेटफ़ॉर्म आपके स्कोर और गतिविधि का समय रिकॉर्ड करता है।',
  how_this_helps_hi = 'सत्रों में एक सरल हिट दर, जो हाथ से गिने बिना सटीकता का सुधार साफ़ दिखा देती है।',
  what_we_dont_measure_hi = 'कैमरा फेंक या वह कहाँ गिरी यह नहीं देखता। आप दर्ज करते हैं; प्लेटफ़ॉर्म आपके टैप रिकॉर्ड करता है। सेंसर हार्डवेयर आने पर यह बदलेगा।',
  mastery_behaviour_hi = 'बच्चा तय दूरी से ज़्यादातर फेंकों में निशाने पर लगाता है।',
  therapist_steps_hi = '["थोड़ी दूर एक टोकरी या निशाना रखें।","बच्चे को बीनबैग या नरम गेंद दें।","उसे निशाने में फेंकने को कहें।","हर फेंक पर लगा या चूका, दर्ज करें।"]'::jsonb,
  materials_required_hi = '["नरम गेंद या बीनबैग","टोकरी या चिह्नित निशाना"]'::jsonb,
