  why_this_works_hi = 'धड़ की ताकत लंबी की बजाय छोटी बार-बार रुकावटों से बनती है। साथ में गिनती बोलना बच्चे को हराने के लिए एक संख्या देता है।',
  what_good_looks_like_hi = 'शुरुआत में बच्चा एक सेकंड रुके या पीठ मोड़ ले। यह अच्छा चल रहा है जब रुकने का समय बढ़े, स्थिति साफ़ रहे, और ज़्यादा बार कर पाएँ।',
