  how_this_helps_hi = 'समय और गिनती के रिकॉर्ड सत्र-दर-सत्र ताकत बढ़ती दिखाते हैं — एक संख्या जो बच्चा भी सुधरती देख सकता है।',
  what_we_dont_measure_hi = 'कैमरा बच्चे की स्थिति, मुद्रा या मेहनत नहीं देखता। आप दर्ज करते हैं; प्लेटफ़ॉर्म आपके टैप रिकॉर्ड करता है। सेंसर हार्डवेयर आने पर यह बदलेगा।',
  mastery_behaviour_hi = 'बच्चा पूरे सेट में तय समय तक स्थिति बनाए रखता है।',
