update activities set
  goal_one_line_hi = 'लक्ष्य: बच्चे को एक नियम से चीज़ें छाँटने में मदद करना।',
  measuring_now_hi = 'बच्चा कितनी देर काम पर ध्यान बनाए रखता है',
  what_this_is_hi = 'मेज़ पर छाँटने का काम जिसमें चीज़ें एक ही गुण से समूहबद्ध होती हैं, कैमरे के पास किया जाता है ताकि ध्यान दर्ज हो सके।',
  why_we_do_it_hi = 'छाँटना आगे के सारे वर्गीकरण की नींव है — अक्षर, अंक, श्रेणियाँ। जो बच्चा एक नियम से छाँट सकता है, वह दो नियमों से छाँटना सीख सकता है।',
  why_this_works_hi = 'एक-नियम छँटाई कई-नियम छँटाई से पहले विकसित होती है। ठोस चीज़ें चित्रों से पहले, और चित्र अमूर्त प्रतीकों से पहले।',
  what_good_looks_like_hi = 'शुरुआत में बच्चा चीज़ें कहीं भी रख सकता है या हर एक के लिए निर्देश चाहिए हो। यह अच्छा चल रहा है जब वे अपने आप सही छाँटें और बिना याद दिलाए पूरा ढेर खत्म करें।',
  what_we_measure_how_hi = 'कैमरा रिकॉर्ड करता है कि बच्चा मेज़ के काम पर कितनी देर ध्यान रखता है और उनका सबसे लंबा निरंतर ध्यान कितना था।',
  how_this_helps_hi = 'सोचने वाले काम के दौरान ध्यान की अवधि दिखाती है कि बच्चा इतनी देर ध्यान रख सकता है या नहीं कि उससे सचमुच कुछ सीख सके।',
  what_we_dont_measure_hi = 'कैमरा यह जाँच नहीं करता कि छँटाई सही थी या नहीं। यह ध्यान मापता है, सही-गलत नहीं। छँटाई आप जाँचते हैं।',
  mastery_behaviour_hi = 'बच्चा बिना निर्देश के दिए गए नियम से पूरा ढेर सही छाँटता है।',
  therapist_steps_hi = '["मेज़ पर दो ट्रे और चीज़ों का ढेर रखें।","एक छँटाई करके दिखाएँ — ''लाल यहाँ, नीला वहाँ''।","बच्चे को अपने आप आगे बढ़ने दें।","अंत में साथ मिलकर जाँचें।"]'::jsonb,
  materials_required_hi = '["ऐसी चीज़ें जो एक बात में अलग हों — रंग, आकार, या माप"]'::jsonb,
  updated_at = now()
where id = 'SPE-ED-01';

update activities set
  goal_one_line_hi = 'लक्ष्य: बच्चे को चित्र और असली चीज़ मिलाने में मदद करना।',
  measuring_now_hi = 'बच्चा कितनी देर काम पर ध्यान बनाए रखता है',
  what_this_is_hi = 'बच्चा चित्र कार्डों को उन असली चीज़ों से मिलाता है जिन्हें वे दर्शाते हैं, मेज़ पर।',
  why_we_do_it_hi = 'यह समझना कि चित्र किसी असली चीज़ का प्रतीक है, एक बड़ा बौद्धिक कदम है। स्कूल की हर किताब इसी पर टिकी है।',
  why_this_works_hi = 'पहले चीज़-से-चीज़ मिलान, फिर चीज़-से-चित्र, फिर चित्र-से-चित्र। हर चरण मज़बूत होने तक अभ्यास किया जाता है।',
  what_good_looks_like_hi = 'शुरुआत में बच्चा बेतरतीब चुन सकता है या कार्ड बिना देखे पकड़े रहे। यह अच्छा चल रहा है जब वे चीज़ों को देखकर सही चुनें, और ज़्यादा जोड़ियों के साथ करें।',
  what_we_measure_how_hi = 'कैमरा रिकॉर्ड करता है कि बच्चा मेज़ पर कितनी देर ध्यान रखता है और उनका सबसे लंबा निरंतर ध्यान कितना था।',
  how_this_helps_hi = 'दिखाता है कि बच्चा मिलान के काम में ध्यान बनाए रख सकता है या नहीं, आपके इस रिकॉर्ड के साथ कि कितने सही हुए।',
  what_we_dont_measure_hi = 'कैमरा यह नहीं जाँचता कि बच्चे ने कौन-सी चीज़ चुनी या वह मेल खाती थी या नहीं। सही-गलत आप दर्ज करते हैं। कैमरा केवल ध्यान मापता है।',
  mastery_behaviour_hi = 'बच्चा बिना संकेत के हर चित्र को उसकी चीज़ से सही मिलाता है।',
  therapist_steps_hi = '["मेज़ पर तीन चीज़ें और उनके चित्र कार्ड रखें।","एक कार्ड दिखाकर वह चीज़ ढूँढ़ने को कहें।","मदद करने से पहले समय दें।","सफल होने पर नई जोड़ियाँ लाएँ।"]'::jsonb,
  materials_required_hi = '["रोज़मर्रा की चीज़ें और उनके चित्र कार्ड"]'::jsonb,
  updated_at = now()
where id = 'SPE-ED-02';

update activities set
  goal_one_line_hi = 'लक्ष्य: बच्चे को उँगली और अँगूठे से छोटी चीज़ें उठाने में मदद करना।',
  measuring_now_hi = 'बच्चा चीज़ें कैसे उठाता है',
  what_this_is_hi = 'बच्चा उँगली और अँगूठे से एक-एक करके छोटी चीज़ें उठाकर डिब्बे में डालता है।',
  why_we_do_it_hi = 'उँगली-अँगूठे की पकड़ ही पेंसिल पकड़ती है। इसके बिना लिखना धीमा और थकाऊ रहता है, चाहे बच्चा अक्षरों का कितना भी अभ्यास करे।',
  why_this_works_hi = 'पकड़ की ताकत और सटीकता इतनी छोटी चीज़ों के दोहराव से बनती है कि उँगली-अँगूठा ज़रूरी हो। बड़ी चीज़ें पूरे हाथ से पकड़ी जा सकती हैं और यह अभ्यास नहीं कराती।',
  what_good_looks_like_hi = 'शुरुआत में बच्चा पूरे हाथ से चीज़ें बटोर सकता है। यह अच्छा चल रहा है जब उँगली और अँगूठा लगातार इस्तेमाल हों और गति तेज़ हो।',
  what_we_measure_how_hi = 'कैमरा हाथ के आकार पहचानता है और उँगली-अँगूठे की पकड़ को पूरे हाथ की पकड़ से अलग गिनता है।',
  how_this_helps_hi = 'विशेष रूप से उँगली-अँगूठे की पकड़ गिनना दिखाता है कि परिपक्व पकड़ विकसित हो रही है या नहीं, केवल काम पूरा हुआ या नहीं।',
  what_we_dont_measure_hi = 'कैमरा हाथ के आकार गिनता है। यह नहीं आँक सकता कि बच्चे ने कितना ज़ोर लगाया या उनका हाथ कितना थका। यह आप आँकते हैं।',
  mastery_behaviour_hi = 'बच्चा पूरे काम में पूरे हाथ की बजाय उँगली और अँगूठे से चीज़ें उठाता है।',
  therapist_steps_hi = '["मेज़ पर, कैमरे के पास, छोटी चीज़ें और एक डिब्बा रखें।","उँगली और अँगूठे से एक उठाकर दिखाएँ।","उन्हें अपने तरीके से डिब्बा भरने दें।","पूरे हाथ से पकड़ने की बजाय उँगली-अँगूठे को प्रोत्साहित करें।"]'::jsonb,
  materials_required_hi = '["छोटी चीज़ें — मोती, खूँटियाँ, सूखा पास्ता","एक डिब्बा"]'::jsonb,
  updated_at = now()
where id = 'SPE-ED-03';

update activities set
  goal_one_line_hi = 'लक्ष्य: बच्चे को रेखाएँ और सरल आकार ट्रेस करने में मदद करना।',
  measuring_now_hi = 'हाथ की हरकत और वे कितनी देर लगे रहते हैं',
  what_this_is_hi = 'बच्चा क्रेयॉन से छपी रेखाएँ और आकार ट्रेस करता है, सीधी रेखाओं से घुमावों की ओर बढ़ते हुए।',
  why_we_do_it_hi = 'ट्रेसिंग हाथ को सिखाती है कि आँख के निर्देश पर रास्ता कैसे चलना है। हर अक्षर इन्हीं रेखाओं और घुमावों का मेल है।',
  why_this_works_hi = 'लिखने से पहले के आकार एक जाने-पहचाने क्रम में विकसित होते हैं — खड़ी, आड़ी, गोला, क्रॉस, वर्ग, त्रिकोण। हर एक अगले से पहले अभ्यास किया जाता है।',
  what_good_looks_like_hi = 'शुरुआत में रेखा बहुत दूर भटक सकती है या बच्चा लकीरें खींचे। यह अच्छा चल रहा है जब ट्रेस रेखा के पास रहे और हाथ ज़्यादा सहजता से चले।',
  what_we_measure_how_hi = 'कैमरा हाथ और पकड़ की गतिविधि गिनता है और रिकॉर्ड करता है कि बच्चा काम में कितनी देर लगा रहा।',
  how_this_helps_hi = 'हाथ की गतिविधि और ध्यान का समय मिलकर दिखाते हैं कि कितना काम हुआ और बच्चा उसे कितनी देर बनाए रख सका।',
  what_we_dont_measure_hi = 'कैमरा कागज़ नहीं देखता और यह नहीं आँकता कि ट्रेसिंग कितनी सही थी। रेखा की गुणवत्ता आप आँकते हैं। कैमरा हाथ की हरकत और ध्यान मापता है।',
  mastery_behaviour_hi = 'बच्चा बिना हाथ पकड़कर मदद के आकार को रेखा पर या उसके पास रहते हुए ट्रेस करता है।',
  therapist_steps_hi = '["मेज़ पर, कैमरे के पास, ट्रेसिंग शीट रखें।","एक रेखा धीरे-धीरे ट्रेस करके दिखाएँ।","उन्हें ट्रेस करने दें, ज़रूरत हो तभी हाथ पकड़कर मदद करें।","सीधी रेखाओं से घुमावदार, फिर आकारों की ओर बढ़ें।"]'::jsonb,
  materials_required_hi = '["ट्रेसिंग शीट","मोटे क्रेयॉन या मार्कर"]'::jsonb,
  updated_at = now()
where id = 'SPE-ED-04';

update activities set
  goal_one_line_hi = 'लक्ष्य: बच्चे को शिक्षक जैसे निर्देश मानने में मदद करना।',
  measuring_now_hi = 'आप हर प्रयास दर्ज करते हैं · हम समय रिकॉर्ड करते हैं',
  what_this_is_hi = 'कक्षा की चीज़ों और दिनचर्या से दो हिस्सों वाले निर्देश, एक बार सामान्य गति से दिए जाते हैं, जैसे शिक्षक देते हैं।',
  why_we_do_it_hi = 'स्कूल पूरे समूह को एक बार दिए गए निर्देशों पर चलता है। जो बच्चा उन्हें नहीं मान पाता वह क्षमता होते हुए भी पाठ चूक जाता है।',
  why_this_works_hi = 'असली कक्षा की भाषा और चीज़ों के साथ अभ्यास अमूर्त कामों से बेहतर काम आता है। निर्देश एक बार दिए जाते हैं, जैसे कक्षा में होते हैं।',
  what_good_looks_like_hi = 'शुरुआत में बच्चा केवल पहला हिस्सा करे या दोहराने का इंतज़ार करे। यह अच्छा चल रहा है जब एक बार कहने पर दोनों हिस्से क्रम में हो जाएँ।',
  what_we_measure_how_hi = 'आप हर प्रयास टैप करके दर्ज करते हैं — दोनों हिस्से, आंशिक, या मदद चाहिए थी। प्लेटफ़ॉर्म आपके स्कोर और गतिविधि का समय रिकॉर्ड करता है।',
  how_this_helps_hi = 'सत्रों में मदद के स्तर की दर्ज दिखाती है कि बच्चा कक्षा के निर्देश अपने आप संभालने लायक हो रहा है या नहीं।',
  what_we_dont_measure_hi = 'कैमरा यह नहीं जाँचता कि निर्देश माना गया या नहीं। आप दर्ज करते हैं; प्लेटफ़ॉर्म वही रिकॉर्ड करता है जो आप टैप करते हैं।',
  mastery_behaviour_hi = 'बच्चा एक बार निर्देश सुनकर दोनों हिस्से क्रम में पूरे करता है।',
  therapist_steps_hi = '["दो हिस्सों वाला निर्देश दें — ''किताब रखो, फिर बैठ जाओ''।","एक बार, सामान्य गति से कहें।","रुकें और देखें कि वे क्या करते हैं।","दर्ज करें: दोनों हिस्से क्रम में, आंशिक, या मदद चाहिए थी।"]'::jsonb,
  materials_required_hi = '["कक्षा जैसी चीज़ें — किताब, बैग, पेंसिल"]'::jsonb,
  updated_at = now()
where id = 'SPE-ED-05';

update activities set
  goal_one_line_hi = 'लक्ष्य: बच्चे को अक्षरों को उनकी ध्वनि से जोड़ने में मदद करना।',
  measuring_now_hi = 'बच्चा कितनी देर काम पर ध्यान बनाए रखता है',
  what_this_is_hi = 'बच्चा बोली गई ध्वनियों को छपे अक्षरों से मिलाता है, छोटे समूह से शुरू करके जो सफलता के साथ बढ़ता है।',
  why_we_do_it_hi = 'ध्वनि को अक्षर से जोड़ना पढ़ना सीखने का सबसे महत्वपूर्ण कौशल है। यहाँ की कठिनाई ही डिस्लेक्सिया का मूल है।',
  why_this_works_hi = 'ध्वनि-अक्षर का मेल एक बार में छोटे समूह से सिखाया जाता है, और जोड़ने से पहले उसमें महारत ली जाती है। मिलते-जुलते अक्षर साथ पढ़ाने की बजाय अलग रखे जाते हैं।',
  what_good_looks_like_hi = 'शुरुआत में बच्चा अंदाज़ा लगाए या मिलते-जुलते अक्षरों में उलझे। यह अच्छा चल रहा है जब वे सही अक्षर ज़्यादा बार, तेज़ी से ढूँढ़ें और एक साथ ज़्यादा अक्षर संभालें।',
  what_we_measure_how_hi = 'कैमरा रिकॉर्ड करता है कि बच्चा अक्षरों पर कितनी देर ध्यान रखता है और उनका सबसे लंबा निरंतर ध्यान कितना था।',
  how_this_helps_hi = 'अक्षरों के काम में लगातार ध्यान मायने रखता है — जो बच्चा कार्डों पर ध्यान नहीं रख पाता वह ये जोड़ नहीं बना सकता, क्षमता चाहे जो हो।',
  what_we_dont_measure_hi = 'कैमरा यह नहीं जाँचता कि बच्चे ने कौन-सा अक्षर चुना या वह सही था। सही-गलत आप दर्ज करते हैं। कैमरा केवल ध्यान मापता है।',
  mastery_behaviour_hi = 'बच्चा बिना संकेत के मौजूदा समूह की हर ध्वनि के लिए सही अक्षर पहचानता है।',
  therapist_steps_hi = '["मेज़ पर तीन-चार अक्षर कार्ड रखें।","एक ध्वनि बोलकर वह अक्षर ढूँढ़ने को कहें।","समय दें — जवाब में जल्दबाज़ी न कराएँ।","मज़बूत होने पर और अक्षर जोड़ें।"]'::jsonb,
  materials_required_hi = '["अक्षर कार्ड"]'::jsonb,
  updated_at = now()
where id = 'SPE-ED-06';

update activities set
  goal_one_line_hi = 'लक्ष्य: बच्चे को अलग-अलग ध्वनियाँ जोड़कर शब्द बनाने में मदद करना।',
  measuring_now_hi = 'बच्चे की आवाज़ें और प्रयास',
  what_this_is_hi = 'बच्चा अलग-अलग ध्वनियाँ सुनकर या बोलकर उन्हें पूरे शब्द में जोड़ता है, तीन ध्वनियों वाले शब्दों से शुरू करते हुए।',
  why_we_do_it_hi = 'जोड़ना ही वह है जो अक्षरों के ज्ञान को पढ़ने में बदलता है। बच्चा हर अक्षर की ध्वनि जानते हुए भी तब तक नहीं पढ़ सकता जब तक जोड़ न सके।',
  why_this_works_hi = 'जोड़ना पहले लगातार चलने वाली ध्वनियों से सिखाया जाता है, और तीन-ध्वनि शब्द लंबे शब्दों से पहले। ध्वनियाँ ज़ोर से बोलना जोड़ में मदद करता है।',
  what_good_looks_like_hi = 'शुरुआत में बच्चा अलग ध्वनियाँ दोहराए बिना जोड़े। यह अच्छा चल रहा है जब पूरा शब्द निकले और लंबे शब्द संभाले जा सकें।',
  what_we_measure_how_hi = 'माइक्रोफ़ोन बच्चे के बोलने के प्रयास गिनता है और रिकॉर्ड करता है कि वे अपने आप आए या आपके बोलने के बाद।',
  how_this_helps_hi = 'दिखाता है कि बच्चा आपकी नकल करने की बजाय खुद जोड़ने की कोशिश कर रहा है या नहीं।',
  what_we_dont_measure_hi = 'माइक्रोफ़ोन सुनता है कि आवाज़ हुई। यह शब्द नहीं पहचानता और यह नहीं जाँचता कि जोड़ सही था — यह आप आँकते हैं।',
  mastery_behaviour_hi = 'बच्चा आपके बोलने से पहले ध्वनियों को जोड़कर सही शब्द बनाता है।',
  therapist_steps_hi = '["एक छोटा शब्द धीरे-धीरे बोलें, ध्वनि दर ध्वनि — ''क... म... ल''।","बच्चे से पूछें कि शब्द क्या है।","उन्हें खुद ध्वनियाँ बोलने दें, फिर जोड़ने दें।","सफल होने पर लंबे शब्दों की ओर बढ़ें।"]'::jsonb,
  materials_required_hi = '["अक्षर कार्ड या व्हाइटबोर्ड"]'::jsonb,
  updated_at = now()
where id = 'SPE-ED-07';

update activities set
  goal_one_line_hi = 'लक्ष्य: बच्चे को अक्षर और शब्द साफ़ नकल करने में मदद करना।',
  measuring_now_hi = 'हाथ की हरकत और वे कितनी देर लगे रहते हैं',
  what_this_is_hi = 'बच्चा नमूने से अक्षर और छोटे शब्द लाइन वाले कागज़ पर नकल करता है, मेज़ पर काम करते हुए।',
  why_we_do_it_hi = 'सही नकल करने के लिए आँख को आकार याद रखना और हाथ को उसे बनाना पड़ता है। यहाँ की कठिनाई पूरे स्कूल में धीमे, मेहनत भरे लेखन के रूप में दिखती है।',
  why_this_works_hi = 'नकल करना याद से लिखने से पहले विकसित होता है। लाइनें बच्चे को माप और जगह का वह फ़ीडबैक देती हैं जो उन्हें चाहिए।',
  what_good_looks_like_hi = 'शुरुआत में अक्षर असमान, बहुत बड़े या लाइन से हटे हो सकते हैं। यह अच्छा चल रहा है जब माप एक जैसा हो, अक्षर लाइन पर बैठें, और बच्चा कम थके।',
  what_we_measure_how_hi = 'कैमरा हाथ और पकड़ की गतिविधि गिनता है और रिकॉर्ड करता है कि बच्चा लिखने के काम में कितनी देर लगा रहा।',
  how_this_helps_hi = 'यहाँ ध्यान की अवधि मायने रखती है — लिखने की कठिनाई अक्सर खराब लिखने की बजाय जल्दी रुक जाने के रूप में दिखती है। समय का रिकॉर्ड यह दिखा देता है।',
  what_we_dont_measure_hi = 'कैमरा कागज़ नहीं देखता और अक्षरों को नहीं आँकता। यह हाथ की गतिविधि और ध्यान मापता है। लिखावट आप आँकते हैं।',
  mastery_behaviour_hi = 'बच्चा पूरा नमूना नकल करता है, अक्षर लाइन पर और एक जैसे माप के।',
  therapist_steps_hi = '["मेज़ पर, कैमरे के पास, लाइन वाला कागज़ और नमूना रखें।","जो दिख रहा है उसे नकल करने को कहें, आराम से।","नतीजे से ज़्यादा पेंसिल की पकड़ देखें।","अंत में साथ मिलकर काम जाँचें।"]'::jsonb,
  materials_required_hi = '["लाइन वाला कागज़","पेंसिल","नकल करने के लिए एक नमूना"]'::jsonb,
  updated_at = now()
where id = 'SPE-ED-08';

update activities set
  goal_one_line_hi = 'लक्ष्य: बच्चे को चीज़ें सही गिनने में मदद करना।',
  measuring_now_hi = 'बच्चा कितनी देर काम पर ध्यान बनाए रखता है',
  what_this_is_hi = 'बच्चा हर चीज़ को छूकर असली चीज़ें गिनता है, और सटीकता बढ़ने पर संख्या बढ़ाई जाती है।',
  why_we_do_it_hi = 'एक-के-बदले-एक मिलान के साथ चीज़ें गिनना पूरे गणित की नींव है। यहाँ की कठिनाई ही डिस्कैलकुलिया का मूल है।',
  why_this_works_hi = 'एक-के-बदले-एक मिलान — हर छुई गई चीज़ पर एक संख्या — आगे गिनने या समूह में गिनने से पहले सिखाया जाता है। हर चीज़ को छूना उसे टिकाता है।',
  what_good_looks_like_hi = 'शुरुआत में बच्चा चीज़ें छोड़ दे, दो बार गिने, या बिना मिलाए संख्याएँ बोलता जाए। यह अच्छा चल रहा है जब हर चीज़ एक बार छुई जाए और कुल सही हो।',
  what_we_measure_how_hi = 'कैमरा रिकॉर्ड करता है कि बच्चा गिनने के काम पर कितनी देर ध्यान रखता है और उनका सबसे लंबा निरंतर ध्यान कितना था।',
  how_this_helps_hi = 'गिनने की गलतियाँ अक्सर बीच में ध्यान हटने से आती हैं। ध्यान का रिकॉर्ड दिखाता है कि असली कठिनाई ध्यान है या संख्या का ज्ञान।',
  what_we_dont_measure_hi = 'कैमरा चीज़ें नहीं देखता और गिनती नहीं जाँचता। सही-गलत आप दर्ज करते हैं। कैमरा केवल ध्यान मापता है।',
  mastery_behaviour_hi = 'बच्चा हर चीज़ को एक बार छूते हुए पूरा समूह सही गिनता है।',
  therapist_steps_hi = '["मेज़ पर चीज़ों का छोटा समूह रखें।","बच्चे से हर एक को छूते हुए गिनने को कहें।","आप साथ में न गिनें — उन्हें खुद गिनने दें।","सही होने पर संख्या बढ़ाएँ।"]'::jsonb,
  materials_required_hi = '["गिनने लायक चीज़ें — ब्लॉक, बटन, काउंटर"]'::jsonb,
  updated_at = now()
where id = 'SPE-ED-09';

update activities set
  goal_one_line_hi = 'लक्ष्य: बच्चे को छोटा वाक्य ज़ोर से पढ़ने में मदद करना।',
  measuring_now_hi = 'बच्चा कितना ज़ोर से पढ़ता है',
  what_this_is_hi = 'बच्चा छोटे सरल वाक्य ज़ोर से पढ़ता है, और शब्द बताने की बजाय उन्हें खुद निकालने का समय दिया जाता है।',
  why_we_do_it_hi = 'ज़ोर से पढ़ना ठीक-ठीक दिखाता है कि कठिनाई कहाँ है — अक्षर पहचानने में, प्रवाह में, या समझने में। यह कोशिश करने का आत्मविश्वास भी बनाता है।',
  why_this_works_hi = 'शब्द बताने की बजाय इंतज़ार करना बच्चे को जोड़ना लागू करने का मौका देता है। बाद में मतलब पर बात करना पढ़ने को अर्थ से जोड़े रखता है।',
  what_good_looks_like_hi = 'शुरुआत में बच्चा शब्द-दर-शब्द पढ़े या अनजान शब्दों पर रुक जाए। यह अच्छा चल रहा है जब पढ़ना ज़्यादा बहे, कम शब्द अटकाएँ, और वे बता सकें कि मतलब क्या था।',
  what_we_measure_how_hi = 'माइक्रोफ़ोन रिकॉर्ड करता है कि बच्चा कितना बोला और आपकी तथा उनकी आवाज़ का संतुलन क्या रहा।',
  how_this_helps_hi = 'कुल पढ़ने का समय और बोलने का संतुलन दिखाता है कि पढ़ना बच्चा कर रहा है या ज़्यादातर आप बता रहे हैं।',
  what_we_dont_measure_hi = 'माइक्रोफ़ोन मापता है कि कितना कहा गया, क्या नहीं। यह नहीं जाँच सकता कि शब्द सही पढ़े गए — यह पूरी तरह आपका आकलन है।',
  mastery_behaviour_hi = 'बच्चा बिना शब्द बताए जाने के वाक्य ज़ोर से पढ़ता है।',
  therapist_steps_hi = '["एक बार में एक छोटा वाक्य दिखाएँ।","बच्चे से अपनी गति से ज़ोर से पढ़ने को कहें।","शब्द बताने की बजाय इंतज़ार करें।","उसका मतलब क्या था, इस पर थोड़ी बात करें।"]'::jsonb,
  materials_required_hi = '["कार्ड या किताब पर छोटे सरल वाक्य"]'::jsonb,
  updated_at = now()
where id = 'SPE-ED-10';

update activities set
  goal_one_line_hi = 'लक्ष्य: बच्चे को घटनाओं को सही क्रम में लगाने में मदद करना।',
  measuring_now_hi = 'बच्चा कितनी देर काम पर ध्यान बनाए रखता है',
  what_this_is_hi = 'बच्चा बिखरे चित्र कार्डों को सही क्रम में लगाता है और फिर कहानी सुनाता है।',
  why_we_do_it_hi = 'यह समझना कि घटनाओं का एक क्रम होता है, पढ़ने की समझ, लिखने और यह बताने की नींव है कि क्या हुआ। यह हर विषय में चाहिए।',
  why_this_works_hi = 'तीन-कार्ड क्रम चार या पाँच से पहले सिखाए जाते हैं। बाद में कहानी सुनाना जाँचता है कि क्रम समझा गया था या अंदाज़ा लगाया गया।',
  what_good_looks_like_hi = 'शुरुआत में बच्चा बेतरतीब क्रम लगाए या एक ही कार्ड पर ध्यान दे। यह अच्छा चल रहा है जब क्रम ज़्यादा बार सही हो और वे बता सकें कि क्यों।',
  what_we_measure_how_hi = 'कैमरा रिकॉर्ड करता है कि बच्चा कार्डों पर कितनी देर ध्यान रखता है और उनका सबसे लंबा निरंतर ध्यान कितना था।',
  how_this_helps_hi = 'दिखाता है कि बच्चा तर्क वाले काम में ध्यान बनाए रख सकता है या नहीं, जो इससे अलग है कि उन्हें जवाब पता है या नहीं।',
  what_we_dont_measure_hi = 'कैमरा कार्डों का क्रम नहीं देखता और यह नहीं जाँचता कि वह सही था। वह आप दर्ज करते हैं। कैमरा केवल ध्यान मापता है।',
  mastery_behaviour_hi = 'बच्चा पूरा क्रम सही लगाता है और उसे समझा सकता है।',
  therapist_steps_hi = '["तीन-चार चित्र कार्ड बिखेरकर रखें।","बच्चे से उन्हें घटने के क्रम में लगाने को कहें।","उन्हें खुद कार्ड हिलाने दें।","क्रम लगने पर कहानी सुनाने को कहें।"]'::jsonb,
  materials_required_hi = '["सरल क्रम दिखाने वाले चित्र कार्ड"]'::jsonb,
  updated_at = now()
where id = 'SPE-ED-11';

update activities set
  goal_one_line_hi = 'लक्ष्य: बच्चे को दूर से सही नकल करने में मदद करना।',
  measuring_now_hi = 'बच्चा कितनी देर काम पर ध्यान बनाए रखता है',
  what_this_is_hi = 'बच्चा दूर रखे बोर्ड से लिखा हुआ कागज़ पर उतारता है, हर हिस्से को याद रखते हुए जब वे नज़र हटाते हैं।',
  why_we_do_it_hi = 'बोर्ड से उतारना स्कूल की सबसे आम माँगों में से एक है और सीखने की कठिनाई वाले बच्चों के लिए सबसे मुश्किल में से एक। इसमें एक साथ याददाश्त, नज़र और लिखना चाहिए।',
  why_this_works_hi = 'पास से नकल करना दूर से नकल करने से पहले सिखाया जाता है। कठिनाई यह है कि नज़र हटाकर वापस लाने तक लिखा हुआ याद रखना — यह कार्यशील स्मृति की माँग है, केवल लिखने की नहीं।',
  what_good_looks_like_hi = 'शुरुआत में बच्चा अक्षर-दर-अक्षर उतारे, जगह भूल जाए, या शब्द छोड़ दे। यह अच्छा चल रहा है जब वे एक नज़र में ज़्यादा ले जाएँ, अपनी जगह बनाए रखें, और जल्दी खत्म करें।',
  what_we_measure_how_hi = 'कैमरा रिकॉर्ड करता है कि बच्चा काम में कितनी देर लगा रहा और मेज़ पर उनका सबसे लंबा निरंतर ध्यान कितना था।',
  how_this_helps_hi = 'बोर्ड से उतारना अक्सर अक्षमता की बजाय थकान से बिगड़ता है। ध्यान का रिकॉर्ड दिखाता है कि बच्चा कब रुका, केवल यह नहीं कि उन्होंने क्या लिखा।',
  what_we_dont_measure_hi = 'कैमरा बोर्ड या कागज़ नहीं देखता और सही-गलत नहीं जाँच सकता। नकल आप जाँचते हैं। कैमरा केवल ध्यान मापता है।',
  mastery_behaviour_hi = 'बच्चा अपनी जगह खोए बिना पूरा लिखा हुआ सही उतारता है।',
  therapist_steps_hi = '["कमरे के दूसरी ओर बोर्ड पर कुछ पंक्तियाँ लिखें।","बच्चे से मेज़ पर कागज़ पर उतारने को कहें।","न दोहराएँ, न ज़ोर से पढ़ें।","अंत में साथ मिलकर नकल जाँचें।"]'::jsonb,
  materials_required_hi = '["दूर रखा व्हाइटबोर्ड या चार्ट","कागज़ और पेंसिल"]'::jsonb,
  updated_at = now()
where id = 'SPE-ED-12';

update activities set
  goal_one_line_hi = 'लक्ष्य: बच्चे को शुरू करने से पहले काम की योजना बनाने में मदद करना।',
  measuring_now_hi = 'आप हर प्रयास दर्ज करते हैं · हम समय रिकॉर्ड करते हैं',
  what_this_is_hi = 'बच्चे को कई हिस्सों वाला काम दिया जाता है और शुरू करने से पहले उसे चरणों में बाँटने को कहा जाता है, फिर वे अपनी योजना पर काम करते हैं।',
  why_we_do_it_hi = 'बड़े बच्चे स्कूल के काम में क्षमता की कमी से ज़्यादा खराब योजना से पिछड़ते हैं। काम को तोड़ना सीखना ऐसा कौशल है जो हर जगह काम आता है।',
  why_this_works_hi = 'योजना बनाने को करने से अलग और स्पष्ट रखना ही आदत बनाता है। चरण लिखना उसे बाहर निकाल देता है जो वरना दिमाग में रखना पड़ता।',
  what_good_looks_like_hi = 'शुरुआत में बच्चा बिना योजना के तुरंत शुरू कर दे, या योजना बनाकर छोड़ दे। यह अच्छा चल रहा है जब वे पहले योजना बनाएँ और अपने ही चरणों पर काम करें।',
  what_we_measure_how_hi = 'आप हर प्रयास टैप करके दर्ज करते हैं — योजना बनाई या नहीं, उसका पालन किया या नहीं, और कितनी मदद चाहिए थी। प्लेटफ़ॉर्म आपके स्कोर और समय रिकॉर्ड करता है।',
  how_this_helps_hi = '''योजना बनाई'' को ''उसका पालन किया'' से अलग करना दिखाता है कि कौशल के किस आधे हिस्से पर काम चाहिए, जो एक ही स्कोर छिपा देता।',
  what_we_dont_measure_hi = 'कैमरा काम या योजना नहीं देखता। आप दर्ज करते हैं; प्लेटफ़ॉर्म आपके टैप रिकॉर्ड करता है और काम का समय मापता है।',
  mastery_behaviour_hi = 'बच्चा शुरू करने से पहले काम को चरणों में बाँटता है और अपनी ही योजना पर काम करता है।',
  therapist_steps_hi = '["कई हिस्सों वाला काम दें।","शुरू करने से पहले पूछें कि चरण क्या होंगे।","उन्हें बोलकर या कागज़ पर योजना बनाने दें।","दर्ज करें कि योजना बनाई या नहीं, और उसका पालन किया या नहीं।"]'::jsonb,
  materials_required_hi = '["कई हिस्सों वाला काम — वर्कशीट, शिल्प, सफ़ाई"]'::jsonb,
  updated_at = now()
where id = 'SPE-ED-13';

-- 0059 part 3 of 3 — Hindi for new activities

update activities set
  goal_one_line_hi = 'लक्ष्य: बच्चे को अपनी गलतियाँ खुद ढूँढ़ने में मदद करना।',
  measuring_now_hi = 'आप हर प्रयास दर्ज करते हैं · हम समय रिकॉर्ड करते हैं',
  what_this_is_hi = 'बच्चा पूरा किया हुआ काम जाँचता है जिसमें जानबूझकर गलतियाँ रखी गई हैं, और बिना बताए उन्हें ढूँढ़ता है।',
  why_we_do_it_hi = 'अपना काम जाँचना ही एक लापरवाह गलती को बार-बार होने वाली गलती से अलग करता है। सीखने की कठिनाई वाले ज़्यादातर बच्चों को यह कभी सिखाया ही नहीं जाता।',
  why_this_works_hi = 'किसी और के काम में गलतियाँ ढूँढ़ना अपने काम से आसान है और पहले अभ्यास किया जाता है। गलतियों की ज्ञात संख्या बच्चे को लक्ष्य देती है।',
  what_good_looks_like_hi = 'शुरुआत में बच्चा बिना देखे कह दे कि हो गया, या केवल साफ़ दिखने वाली गलतियाँ ढूँढ़े। यह अच्छा चल रहा है जब वे व्यवस्थित रूप से जाँचें और ज़्यादा ढूँढ़ें।',
  what_we_measure_how_hi = 'आप हर प्रयास टैप करके दर्ज करते हैं कि कितनी गलतियाँ मिलीं। प्लेटफ़ॉर्म आपके स्कोर और गतिविधि का समय रिकॉर्ड करता है।',
  how_this_helps_hi = 'सत्रों में मिली गलतियों की गिनती दिखाती है कि खुद जाँचना आदत बन रहा है या नहीं, बजाय इसके कि आपको कहना पड़े।',
  what_we_dont_measure_hi = 'कैमरा काम या सुधार नहीं देखता। आप दर्ज करते हैं; प्लेटफ़ॉर्म आपके टैप रिकॉर्ड करता है।',
  mastery_behaviour_hi = 'बच्चा बिना बताए ज़्यादातर गलतियाँ खुद ढूँढ़ लेता है।',
  therapist_steps_hi = '["बच्चे को पूरा किया हुआ काम दें जिसमें कुछ गलतियाँ हों।","उनसे गलत क्या है ढूँढ़कर ठीक करने को कहें।","गलतियों की ओर इशारा न करें।","दर्ज करें कि उन्होंने अपने आप कितनी ढूँढ़ीं।"]'::jsonb,
  materials_required_hi = '["जानबूझकर कुछ गलतियों वाला पूरा किया हुआ काम"]'::jsonb,
  updated_at = now()
where id = 'SPE-ED-14';

update activities set
  goal_one_line_hi = 'लक्ष्य: बच्चे को तय समय में लगातार काम करने में मदद करना।',
  measuring_now_hi = 'बच्चा कितनी देर काम पर ध्यान बनाए रखता है',
  what_this_is_hi = 'बच्चा चलते हुए timer के साथ काम करता है, तय की गई मात्रा उसके खत्म होने से पहले पूरी करने का लक्ष्य रखते हुए।',
  why_we_do_it_hi = 'स्कूल का काम समय से बँधा होता है — पाठ, परीक्षा, गृहकार्य। जो बच्चा अपनी गति नहीं संभाल पाता, उसका समय खत्म हो जाता है चाहे उसे कितना भी आता हो।',
  why_this_works_hi = 'दिखने वाला timer समय को बाहर ला देता है, जिसे सीखने की कठिनाई वाले बच्चे अक्सर गलत आँकते हैं। बाद में देखना उनकी अपनी गति की समझ बनाता है।',
  what_good_looks_like_hi = 'शुरुआत में बच्चा जल्दबाज़ी में गलतियाँ करे, या धीरे काम करके खत्म न कर पाए। यह अच्छा चल रहा है जब गति स्थिर हो और उसी समय में ज़्यादा सही काम हो।',
  what_we_measure_how_hi = 'कैमरा रिकॉर्ड करता है कि बच्चा मेज़ पर कितनी देर ध्यान रखता है और उनका सबसे लंबा निरंतर काम कितना था।',
  how_this_helps_hi = 'घड़ी के मुकाबले काम पर लगे रहने का समय दिखाता है कि बच्चा पूरे समय काम कर रहा है या बीच के हिस्से खो रहा है।',
  what_we_dont_measure_hi = 'कैमरा मेज़ पर ध्यान मापता है, यह नहीं कि क्या बना या वह सही था। काम आप आँकते हैं।',
  mastery_behaviour_hi = 'बच्चा बिना याद दिलाए तय समय में तय मात्रा पूरी करता है।',
  therapist_steps_hi = '["मेज़ पर एक छोटा काम और दिखने वाला timer रखें।","तय करें कि खत्म होने से पहले क्या पूरा होना चाहिए।","उन्हें काम करने दें — समय की याद न दिलाएँ।","साथ मिलकर देखें कि कितना हो पाया।"]'::jsonb,
  materials_required_hi = '["एक छोटा काम","दिखने वाला timer"]'::jsonb,
  updated_at = now()
where id = 'SPE-ED-15';

update activities set
  goal_one_line_hi = 'लक्ष्य: बच्चे को अपनी पसंद के बारे में बोलने और फिर सुनने में मदद करना।',
  measuring_now_hi = 'आप दोनों कितना बोलते हैं',
  what_this_is_hi = 'बच्चा अपनी किसी गहरी पसंद के बारे में बोलता है, फिर बातचीत मोड़ी जाती है ताकि उन्हें सुनना और आपसे पूछना पड़े।',
  why_we_do_it_hi = 'ऑटिज़्म वाले कई बच्चे अपनी पसंद पर लंबा बोल सकते हैं पर सुनने वाला आधा हिस्सा कठिन लगता है। दोस्ती के लिए दोनों आधे चाहिए।',
  why_this_works_hi = 'बच्चे की अपनी पसंद से शुरू करना उन्हें खुलकर बोलने देता है। जो कौशल बन रहा है वह वह बारी है जहाँ बातचीत किसी और की ओर मुड़ती है।',
  what_good_looks_like_hi = 'शुरुआत में बच्चा बिना रुके बोले और आपकी बारी में रुचि न दिखाए। यह अच्छा चल रहा है जब वे रुकें, आपसे कुछ पूछें, और थोड़ी देर आपके विषय पर रहें।',
  what_we_measure_how_hi = 'माइक्रोफ़ोन आपकी आवाज़ उनकी आवाज़ से अलग करता है और रिकॉर्ड करता है कि आप दोनों कितना बोले और बारियाँ कैसे बदलीं।',
  how_this_helps_hi = 'बोलने का संतुलन वस्तुनिष्ठ रूप से दिखाता है कि बातचीत दोनों तरफ़ गई या नहीं — जिसे उसमें रहते हुए आँकना बहुत कठिन है।',
  what_we_dont_measure_hi = 'माइक्रोफ़ोन मापता है कि कौन कब बोला, क्या कहा या वे सचमुच रुचि रखते थे या नहीं यह नहीं। यह आप आँकते हैं।',
  mastery_behaviour_hi = 'बच्चा आपके विषय पर आपसे एक सवाल पूछता है और जवाब सुनता है।',
  therapist_steps_hi = '["उनसे किसी ऐसी चीज़ के बारे में पूछें जो उन्हें बहुत पसंद हो।","कुछ देर बिना टोके उन्हें बोलने दें।","फिर अपनी कोई बात बताएँ और देखें कि वे पूछते हैं या नहीं।","लक्ष्य यह है कि बातचीत दोनों तरफ़ चले।"]'::jsonb,
  materials_required_hi = '[]'::jsonb,
  updated_at = now()
where id = 'AUT-21';

update activities set
  goal_one_line_hi = 'लक्ष्य: बच्चे को यह समझने में मदद करना कि लोगों के बीच क्या हो रहा है।',
  measuring_now_hi = 'बच्चा कितनी देर काम पर ध्यान बनाए रखता है',
  what_this_is_hi = 'बच्चा रोज़मर्रा की सामाजिक स्थितियों के चित्र देखकर बताता है कि लोगों के बीच क्या हो रहा है और उन्हें कैसे पता चला।',
  why_we_do_it_hi = 'बड़े ऑटिज़्म वाले बच्चे अक्सर अकेली भावना समझ लेते हैं पर पूरी स्थिति चूक जाते हैं। माहौल पढ़ पाना ही स्कूल और दोस्ती को संभालने लायक बनाता है।',
  why_this_works_hi = 'एक चेहरे को नाम देने से पूरे दृश्य की व्याख्या करने तक जाना विकास का कदम है। ''तुम्हें कैसे पता चला'' पूछना संकेतों को अनुमान की बजाय स्पष्ट बनाता है।',
  what_good_looks_like_hi = 'शुरुआत में बच्चा जो दिख रहा है उसे शाब्दिक रूप से बताए बिना व्याख्या के। यह अच्छा चल रहा है जब वे बताएँ कि क्या हो रहा है और संकेत भी बता सकें।',
  what_we_measure_how_hi = 'कैमरा रिकॉर्ड करता है कि बच्चा चित्रों पर कितनी देर ध्यान रखता है और उनका सबसे लंबा निरंतर ध्यान कितना था।',
  how_this_helps_hi = 'दिखाता है कि बच्चा सामाजिक रूप से माँग वाले काम में ध्यान बनाए रख सकता है या नहीं, जो इससे अलग है कि उन्हें जवाब पता है या नहीं।',
  what_we_dont_measure_hi = 'कैमरा उनकी व्याख्या या वह सही थी या नहीं यह नहीं जाँचता। यह आप आँकते हैं। कैमरा केवल ध्यान मापता है।',
  mastery_behaviour_hi = 'बच्चा बताता है कि क्या हो रहा है और वह संकेत बताता है जिससे उन्हें पता चला।',
  therapist_steps_hi = '["किसी असली सामाजिक स्थिति का चित्र दिखाएँ।","पूछें कि लोगों के बीच क्या चल रहा है।","पूछें कि उन्हें कैसे पता चला — संकेत क्या था।","जो संकेत वे चूके, उन पर बात करें।"]'::jsonb,
  materials_required_hi = '["रोज़मर्रा की सामाजिक स्थितियों की तस्वीरें या छोटी क्लिप"]'::jsonb,
  updated_at = now()
where id = 'AUT-22';

update activities set
  goal_one_line_hi = 'लक्ष्य: बच्चे को साथ मिलकर योजना बनाने में मदद करना, देते और लेते हुए।',
  measuring_now_hi = 'बच्चा कितनी बार अपने आप बोलता है',
  what_this_is_hi = 'आप और बच्चा साथ मिलकर किसी असली या काल्पनिक कार्यक्रम की योजना बनाते हैं, बारी-बारी सुझाव देते और हिस्सों पर सहमत होते हुए।',
  why_we_do_it_hi = 'साथ योजना बनाने में बच्चे को अपने विचार देने, किसी और के विचार मानने और सहमति तक पहुँचने की ज़रूरत होती है। यह इसके करीब है कि दोस्ती सचमुच कैसे चलती है।',
  why_this_works_hi = 'साझा लक्ष्य बातचीत करने का असली कारण बनाता है। कुछ वयस्क विचारों का अस्वीकार होना इसे आज्ञापालन के अभ्यास की बजाय असली बनाए रखता है।',
  what_good_looks_like_hi = 'शुरुआत में बच्चा अपनी ही योजना पर अड़े या बिना सोचे सब मान ले। यह अच्छा चल रहा है जब वे विचार दें, आपके कुछ विचार मानें, और उन पर आगे बढ़ें।',
  what_we_measure_how_hi = 'माइक्रोफ़ोन बच्चे के योगदान गिनता है और अलग करता है कि कौन-से उन्होंने अपने आप दिए और कौन-से आपके पूछने पर।',
  how_this_helps_hi = 'अपने आप दिए गए योगदान की गिनती दिखाती है कि बच्चा सचमुच साथ योजना बना रहा है या केवल सवालों के जवाब दे रहा है।',
  what_we_dont_measure_hi = 'माइक्रोफ़ोन सुनता है कि बच्चा कब अपने आप बोला। यह नहीं जानता कि उन्होंने क्या सुझाया या वह उचित था — यह आप आँकते हैं।',
  mastery_behaviour_hi = 'बच्चा अपने विचार देता है और आपका कम से कम एक विचार मानता है।',
  therapist_steps_hi = '["साथ मिलकर योजना बनाने के लिए कुछ चुनें — घूमना, पार्टी, खाना।","बारी-बारी उसके हिस्से सुझाएँ।","कुछ आपके विचार चुने जाएँ और कुछ उनके।","इसे सवाल-जवाब नहीं, साथ काम करना बनाए रखें।"]'::jsonb,
