update activities set
  goal_one_line_hi = 'लक्ष्य: बच्चे को अपना सामान इस तरह व्यवस्थित करना कि मिल सके।',
  measuring_now_hi = 'आप हर प्रयास दर्ज करते हैं · हम समय रिकॉर्ड करते हैं',
  what_this_is_hi = 'बच्चा स्कूल बैग खाली करके फिर से लगाता है, उसी व्यवस्था से जिसे बनाने में उन्होंने मदद की, ताकि चीज़ें दोबारा मिल सकें।',
  why_we_do_it_hi = 'खोया हुआ गृहकार्य और भूली हुई किताबें स्कूल और घर पर असली परेशानी बनती हैं। व्यवस्थित रहना सिखाया जा सकने वाला कौशल है, स्वभाव नहीं।',
  why_this_works_hi = 'बच्चे की बनाई व्यवस्था थोपी गई व्यवस्था से ज़्यादा इस्तेमाल होती है। उसी व्यवस्था का बार-बार अभ्यास ही उसे अपने आप होने लायक बनाता है।',
  what_good_looks_like_hi = 'शुरुआत में बच्चा चीज़ें ढेर में डाल दे या हर चीज़ के लिए निर्देश चाहिए हो। यह अच्छा चल रहा है जब वे बिना कहे व्यवस्था से रखें और बाद में चीज़ें ढूँढ़ पाएँ।',
  what_we_measure_how_hi = 'आप हर प्रयास टैप करके दर्ज करते हैं — व्यवस्था का पालन किया, आंशिक, या मदद चाहिए थी। प्लेटफ़ॉर्म आपके स्कोर और समय रिकॉर्ड करता है।',
  how_this_helps_hi = 'मदद के स्तर की दर्ज दिखाती है कि व्यवस्थित रहना अपने आप हो रहा है या कोई बड़ा चला रहा है।',
  what_we_dont_measure_hi = 'कैमरा बैग या चीज़ें कहाँ गईं यह नहीं देखता। आप दर्ज करते हैं; प्लेटफ़ॉर्म आपके टैप रिकॉर्ड करता है।',
  mastery_behaviour_hi = 'बच्चा बिना कहे अपनी ही व्यवस्था से बैग लगाता है।',
  therapist_steps_hi = '["बैग मेज़ पर पूरा खाली करें।","तय करें कि किस तरह की चीज़ कहाँ रहेगी।","उन्हें खुद बैग लगाने दें।","दर्ज करें कि व्यवस्था का पालन किया और कितनी मदद चाहिए थी।"]'::jsonb,
  materials_required_hi = '["स्कूल बैग और उसका सामान"]'::jsonb,
