update activities set
  goal_one_line_hi = 'लक्ष्य: बच्चे को अंदाज़ा लगाने में मदद करना कि काम में कितना समय लगेगा।',
  measuring_now_hi = 'आप हर प्रयास दर्ज करते हैं · हम समय रिकॉर्ड करते हैं',
  what_this_is_hi = 'बच्चा अंदाज़ा लगाता है कि काम में कितना समय लगेगा, फिर उसे मापकर अंदाज़े से मिलाया जाता है।',
  why_we_do_it_hi = 'ADHD वाले बच्चे अक्सर समय बहुत गलत आँकते हैं — जिस गृहकार्य को वे दस मिनट का समझते हैं वह एक घंटा ले लेता है। खराब समय-अनुमान बहुत सारे टालमटोल के पीछे है।',
  why_this_works_hi = 'बार-बार अंदाज़ा-फिर-जाँच अवधि की भीतरी समझ बनाता है। बिना आलोचना के मिलाना ही बच्चे को अंदाज़ा लगाते रहने के लिए तैयार रखता है।',
  what_good_looks_like_hi = 'शुरुआत में अंदाज़े किसी भी दिशा में बहुत गलत हो सकते हैं। यह अच्छा चल रहा है जब अलग-अलग कामों में अंदाज़े असली समय के करीब आने लगें।',
  what_we_measure_how_hi = 'आप हर प्रयास टैप करके अंदाज़ा और असली समय दर्ज करते हैं। प्लेटफ़ॉर्म दोनों और गतिविधि की अवधि रिकॉर्ड करता है।',
  how_this_helps_hi = 'सत्रों में अंदाज़े को असली समय के मुकाबले दर्ज करना दिखाता है कि समय की समझ सचमुच बेहतर हो रही है या नहीं — एक संख्या जो आप दोनों वरना याद नहीं रख पाते।',
  what_we_dont_measure_hi = 'कैमरा काम नहीं देखता। आप अंदाज़ा और नतीजा दर्ज करते हैं; प्लेटफ़ॉर्म उन्हें संग्रहित करता है और काम का समय मापता है।',
  mastery_behaviour_hi = 'बच्चे का अंदाज़ा कई कामों में असली समय के करीब रहता है।',
  therapist_steps_hi = '["काम से पहले पूछें कि उन्हें लगता है कितने मिनट लगेंगे।","अंदाज़ा लिख लें।","बिना टिप्पणी किए काम का समय मापें।","बाद में अंदाज़ा और असली समय साथ मिलाकर देखें।"]'::jsonb,
