  goal_one_line_hi = 'लक्ष्य: बच्चे को कुछ और होते हुए भी काम जारी रखने में मदद करना।',
  measuring_now_hi = 'बच्चा कितनी देर काम पर ध्यान बनाए रखता है',
  what_this_is_hi = 'बच्चा हल्के नियंत्रित ध्यान भटकाव के बीच काम करता है, और बाद में सोचता है कि किस चीज़ ने उनका ध्यान खींचा।',
  why_we_do_it_hi = 'कक्षाएँ शोर और हलचल से भरी होती हैं। केवल शांति में काम करना बच्चे को उस जगह के लिए तैयार नहीं करता जहाँ उन्हें सचमुच ध्यान लगाना है।',
  why_this_works_hi = 'ध्यान भटकाव धीरे-धीरे लाया जाता है और हल्का रखा जाता है। बाद में सोचना उनके अपने ट्रिगर की समझ बनाता है, जो आगे खुद को संभालने देता है।',
  what_good_looks_like_hi = 'शुरुआत में बच्चा ध्यान भटकते ही पूरी तरह रुक जाए। यह अच्छा चल रहा है जब वे अपने आप काम पर लौटें, और खिंचने से पहले ज़्यादा देर टिकें।',
  what_we_measure_how_hi = 'कैमरा रिकॉर्ड करता है कि बच्चा मेज़ पर कितनी देर ध्यान रखता है और ध्यान भटकाव के बावजूद उनका सबसे लंबा निरंतर ध्यान कितना था।',
  how_this_helps_hi = 'ध्यान भटकाव के बीच काम पर लगे रहने का समय शांत कमरे में ध्यान से कहीं ज़्यादा असली माप है, और सत्रों में सीधे तुलना करने लायक है।',
  what_we_dont_measure_hi = 'कैमरा मापता है कि बच्चा कहाँ देख रहा है, यह नहीं कि वे काम के बारे में सोच रहे थे। असली जुड़ाव आप पुष्टि करते हैं।',
  mastery_behaviour_hi = 'बच्चा हर ध्यान भटकाव के बाद बिना याद दिलाए अपने आप काम पर लौटता है।',
  therapist_steps_hi = '["मेज़ पर ऐसा काम रखें जो बच्चा कर सके।","हल्का ध्यान भटकाने वाला कुछ लाएँ — पीछे आवाज़, पास हलचल।","उन्हें ध्यान लगाने की याद दिलाए बिना काम करने दें।","बाद में बात करें कि किस चीज़ ने खींचा।"]'::jsonb,
  materials_required_hi = '["ऐसा काम जो बच्चा कर सके","हल्का नियंत्रित ध्यान भटकाव"]'::jsonb,
