  what_we_measure_how_hi = 'आप हर सत्र टैप करके दर्ज करते हैं — अपने आप याद था, याद दिलाना पड़ा, या दोबारा समझाना पड़ा। प्लेटफ़ॉर्म आपके स्कोर और समय रिकॉर्ड करता है।',
  how_this_helps_hi = 'सत्र-दर-सत्र रिकॉर्ड दिखाते हैं कि बच्चा दिनों के आर-पार लक्ष्य पकड़े रख रहा है या नहीं, जो असल में यही कौशल बन रहा है।',
  what_we_dont_measure_hi = 'कैमरा प्रोजेक्ट या क्या किया गया यह नहीं देखता। आप दर्ज करते हैं; प्लेटफ़ॉर्म आपके टैप रिकॉर्ड करता है।',
  mastery_behaviour_hi = 'बच्चा बिना याद दिलाए सही जगह से प्रोजेक्ट आगे बढ़ाता है।',
  therapist_steps_hi = '["ऐसा प्रोजेक्ट शुरू करें जो एक सत्र में पूरा न हो।","अंत में तय करें कि अगली बार कहाँ से उठाना है।","अगले सत्र में बिना दोबारा समझाए आगे बढ़ने को कहें।","दर्ज करें कि उन्हें याद था और अपने आप आगे बढ़े या नहीं।"]'::jsonb,
