  measuring_now_hi = 'आप दोनों के बीच का आदान-प्रदान',
  what_this_is_hi = 'जानबूझकर हल्की-फुल्की असहमतियाँ बनाई जाती हैं ताकि बच्चा यह कहने का अभ्यास कर सके कि वे अलग सोचते हैं, और कारण दे सकें।',
  why_we_do_it_hi = 'बिना झगड़े असहमत होने के लिए विशेष भाषा चाहिए जो ज़्यादातर बच्चे अपने आप सीख लेते हैं। इसके बिना बच्चा या तो सब मान लेता है या झगड़ पड़ता है।',
  why_this_works_hi = 'सचमुच मामूली विषयों पर अभ्यास भावनात्मक दबाव हटा देता है, ताकि बच्चा बहस की बजाय शब्दों पर ध्यान दे सके।',
  what_good_looks_like_hi = 'शुरुआत में बच्चा हर बात मान ले, या बिना कारण सपाट मना कर दे। यह अच्छा चल रहा है जब वे अलग राय बताएँ और उसका कारण दें।',
  what_we_measure_how_hi = 'माइक्रोफ़ोन रिकॉर्ड करता है कि आप दोनों के बीच बारियाँ कैसे बदलीं और बच्चे ने कितनी जल्दी जवाब दिया।',
  how_this_helps_hi = 'बारियों का बदलना दिखाता है कि आदान-प्रदान बातचीत बना रहा या एकतरफ़ा हो गया।',
  what_we_dont_measure_hi = 'माइक्रोफ़ोन मापता है कि कौन कब बोला, क्या कहा या कितनी विनम्रता से यह नहीं। शब्द आप आँकते हैं।',
  mastery_behaviour_hi = 'बच्चा कहता है कि वे असहमत हैं और कारण देता है, बिना बातचीत बिगड़े।',
  therapist_steps_hi = '["ऐसी बात कहें जिससे आप जानते हैं वे असहमत होंगे।","उनके जवाब का इंतज़ार करें।","ज़रूरत हो तो विनम्र असहमति करके दिखाएँ — ''मुझे अलग लगता है क्योंकि...''","हल्के विषयों पर कुछ दौर अभ्यास करें।"]'::jsonb,
  materials_required_hi = '[]'::jsonb,
  updated_at = now()
where id = 'SPE-17';

update activities set
  goal_one_line_hi = 'लक्ष्य: बच्चे को स्कूल की स्थिति में मदद माँगने में मदद करना।',
  measuring_now_hi = 'बच्चा कितनी बार अपने आप बोलता है',
  what_this_is_hi = 'स्कूल की आम स्थितियाँ अभिनय करके अभ्यास की जाती हैं ताकि बच्चा शिक्षक से जो चाहिए वह माँगना सीखे।',
  why_we_do_it_hi = 'जो बच्चा शिक्षक से मदद नहीं माँग सकता वह उन कारणों से पिछड़ जाता है जिनका क्षमता से कोई लेना-देना नहीं। ये गिनती के, बहुत काम के वाक्य हैं।',
  why_this_works_hi = 'जाने-पहचाने वयस्क के साथ अभिनय दबाव इतना कम कर देता है कि अभ्यास हो सके। वही स्थितियाँ दोहराने से वाक्य हर बार बनाने की बजाय अपने आप आने लगते हैं।',
  what_good_looks_like_hi = 'शुरुआत में बच्चा कुछ न कहे या ध्यान दिए जाने का इंतज़ार करे। यह अच्छा चल रहा है जब वे साफ़ और बिना लंबी झिझक के माँगें, और ज़्यादा स्थितियों में।',
  what_we_measure_how_hi = 'माइक्रोफ़ोन बच्चे की आवाज़ें गिनता है और अलग करता है कि कौन-सी उन्होंने अपने आप शुरू कीं और कौन-सी आपके पूछने पर।',
  how_this_helps_hi = 'अपने आप माँगने की गिनती दिखाती है कि बच्चा पूछे जाने का इंतज़ार करने की बजाय खुद शुरू कर रहा है — इस कौशल का यही पूरा मकसद है।',
  what_we_dont_measure_hi = 'माइक्रोफ़ोन सुनता है कि बच्चा अपने आप बोला। यह नहीं जानता कि उन्होंने ठीक से माँगा या नहीं — यह आप आँकते हैं।',
  mastery_behaviour_hi = 'बच्चा हर अभ्यास की गई स्थिति में बिना संकेत के जो चाहिए वह माँगता है।',
  therapist_steps_hi = '["स्कूल की स्थिति बनाएँ — समझ न आना, किताब न होना, बाथरूम जाना।","शिक्षक बनकर इंतज़ार करें।","शब्द बताने की बजाय उन्हें खुद ढूँढ़ने दें।","वही स्थितियाँ तब तक दोहराएँ जब तक शब्द आसानी से न आएँ।"]'::jsonb,
  materials_required_hi = '[]'::jsonb,
  updated_at = now()
